SELECT raa.id, raa.reservation_id AS reservationId, raa.action_type AS actionType, raa.operator_id AS operatorId, op.name AS operatorName, r.user_id AS userId, u.name AS userName, u.username AS username, r.room_id AS roomId, rm.name AS roomName, r.seat_id AS seatId, s.seat_code AS seatCode, raa.reason, raa.penalty_level AS penaltyLevel, raa.ban_days AS banDays, raa.create_time AS createTime FROM reservation_admin_action raa LEFT JOIN reservation r ON raa.reservation_id = r.id LEFT JOIN user u ON r.user_id = u.id LEFT JOIN user op ON raa.operator_id = op.id LEFT JOIN room rm ON r.room_id = rm.id LEFT JOIN seat s ON r.seat_id = s.id
AND raa.action_type = #{query.actionType}
AND raa.reservation_id = #{query.reservationId}
AND raa.operator_id = #{query.operatorId}
AND u.username LIKE CONCAT('%', #{query.username}, '%')
ORDER BY raa.create_time DESC, raa.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM reservation_admin_action raa
LEFT JOIN reservation r ON raa.reservation_id = r.id
LEFT JOIN user u ON r.user_id = u.id


